<template>
  <div class="v3-workout v3-screen" data-node-id="6741:1367"><sf-page-layout :asset="asset" extended :home-indicator="false">
    <template #header><sf-user-toolbar class="v3-workout__header" :avatar="(user&&user.avatarUrl)||asset('imgEllipse305')" :badge="asset('img40')" profile-class="v3-workout__profile" :actions="toolbarActions" @action="toolbarAction"/></template>
    <sf-segmented-control value="course" :items="modes" label="Workout modes" @change="modeAction"/>
    <sf-workout-carousel :content="content" :image="content.coverUrl||asset('imgRectangle1771')" :back-image="asset('imgRectangle1727')" :image-style="content.coverUrl?null:{left:'-59.78%',top:'-4.75%',width:'219.56%',height:'109.75%'}" :go-layers="[asset('imgEllipse312'),asset('imgEllipse313')]" @start="$emit('action','start-course:'+content.id)"><template v-if="accessLabel" #badge><span class="v3-workout__access commerce-content-label">{{ accessLabel }}</span></template></sf-workout-carousel>
    <div class="v3-workout__devices"><button v-for="device in devices" :key="device.name" type="button" @click="selectDevice(device.name)"><img :src="asset(device.icon)" alt="" data-source-asset="true"><span>{{ device.name }}</span></button></div>
    <sf-button appearance="glass" data-action="existing-categories" @click.stop="categories=true">More Category <img class="v3-workout__more-arrow" :src="asset('img6')" alt="" data-source-asset="true"></sf-button>
    <section class="v3-workout__recommended"><sf-section-title>Recommended Course</sf-section-title><sf-segmented-control v-model="recommendation" :items="recommendations" label="Recommended courses"/><div class="v3-workout__cards"><button v-for="course in visibleCourses" :key="course.id" type="button" class="v3-workout__course" :data-action="'open-course:'+course.id" :aria-label="'View '+course.name" @click.stop="$emit('action','open-course:'+course.id)"><sf-course-card appearance="compact" :title="course.name" :duration="course.durationMinutes+' min'" :image="course.coverUrl||asset('imgRectangle1781')"/></button><sf-feedback v-if="!visibleCourses.length" title="No featured courses available" tone="empty"/></div></section>
    <template #footer><sf-bottom-navigation :items="navigation" active="workout" @select="$emit('action',$event.action)"><template #accessory><button type="button" class="v3-workout__coach" data-action="coach" aria-label="Open AI Coach" @click.stop="$emit('action','coach')"><sf-ai-ball fit :size="56" state="idle" decorative/></button></template></sf-bottom-navigation></template>
  </sf-page-layout><sf-sheet v-model="searching" title="Search courses" contained :resizable="false"><sf-search-field v-model="query" label="Search workouts" placeholder="Search workouts"/><div class="v3-workout__search-results"><sf-menu-row v-for="course in searchResults" :key="course.id" :label="course.name" :description="course.durationMinutes+' min'" @click="openCourse(course.id)"/><sf-feedback v-if="!searchResults.length" tone="empty" title="No matching courses" description="Try another search."/></div></sf-sheet><sf-sheet v-model="categories" title="Course categories" contained :resizable="false"><sf-menu-row v-for="device in devices" :key="device.name" :label="device.name" @click="selectDevice(device.name)"/></sf-sheet></div>
</template>
<script>
import {SfPageLayout,SfWorkoutCarousel,SfSegmentedControl,SfBottomNavigation,SfAiBall,SfButton,SfSectionTitle,SfCourseCard,SfFeedback,SfSheet,SfSearchField,SfMenuRow,SfUserToolbar} from '@/design-system'
import {sceneAsset,workoutNavigation} from '@/design-system/assets/v3-scenes'
export default {name:'V3Workout',components:{SfPageLayout,SfWorkoutCarousel,SfSegmentedControl,SfBottomNavigation,SfAiBall,SfButton,SfSectionTitle,SfCourseCard,SfFeedback,SfSheet,SfSearchField,SfMenuRow,SfUserToolbar},props:{content:{type:Object,required:true},courses:{type:Array,default:()=>[]},user:Object,accessLabel:String},data(){return {searching:false,categories:false,query:'',recommendation:'latest',navigation:workoutNavigation,modes:[{value:'course',label:'Course'},{value:'world',label:'World Tour'},{value:'free',label:'Free Mode'}],recommendations:[{value:'latest',label:'Latest'},{value:'featured',label:'Featured'}],devices:[{name:'Indoor Bike',icon:'img28'},{name:'Treadmill',icon:'img27'},{name:'Rower',icon:'img25'},{name:'Elliptical',icon:'img7'}]}},computed:{toolbarActions(){return [{id:'search',label:'Search courses',icon:this.asset('img8')},{id:'plan',label:'Training calendar',icon:this.asset('imgGroup259')},{id:'existing-free-mode',label:'Free workout mode',icon:this.asset('imgGroup412')}]},visibleCourses(){return this.recommendation==='featured'?this.courses.filter(c=>c.tier==='featured'):this.courses},searchResults(){return this.courses.filter(c=>(c.name+' '+c.description).toLowerCase().includes(this.query.toLowerCase()))}},methods:{toolbarAction(action){if(action==='search')this.searching=true;else this.$emit('action',action)},asset(name){return sceneAsset('workout',name)},modeAction(value){if(value==='course')return;this.$emit('action',value==='world'?'world-tour':'existing-free-mode')},selectDevice(name){this.categories=false;this.query=name;this.searching=true},openCourse(id){this.searching=false;this.$emit('action','open-course:'+id)}}}
</script>
